import {createPairedDuels,stepPairedDuels,pairedPlayer,pairedStandings} from './paired-duels.js';
import {actionFor} from './handling-profile.js';
import {pairAt,random,previewIndex} from './engine.js';
import {OPPONENTS,botProfile,planMove} from './ai.js';
import {drawBoard,drawNext} from './render.js';
import {assignPatterns} from './pattern-pool.js';
import {fallSummary} from './handling-profile.js';

const DT=1000/60,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createPairedDuelsUI({host,prefs,save,read,sound,getPool,showPool,showSettings,onExit}){
 const $=q=>host.querySelector(q),scope=new AbortController(),held=new Map();
 let run=null,difficulty=read('paired-difficulty','medium'),seed=0,countdown=0,paused=false,last=0,acc=0,raf,disposed=false,workers=[],brains=[],actions=[],session=0,saved=false;
 if(!['easy','medium','hard'].includes(difficulty))difficulty='medium';
 const set=(q,s)=>{const el=$(q);if(el&&el.textContent!==String(s))el.textContent=String(s);};
 const cleanup=()=>{workers.forEach(w=>w?.terminate());workers=[];held.clear();actions=[];};
 function setup(){cleanup();run=null;host.innerHTML=`<section class="room-heading"><div><p class="eyebrow">THE SPARRING ROOM · 4 PLAYERS</p><h1>Four players. One winner.</h1></div><button id="paired-exit">Sparring Room</button></section><section class="panel paired-setup"><h2>Paired duels</h2><p>Play against three AI. Two random pairs duel at the same time. Only your matched opponent sends attacks to your board.</p><p class="muted">The first winner waits for the other duel. Survivors keep their boards for the final; queued attacks from the previous opponent are cleared. Last survivor wins.</p><label class="field-label">AI difficulty<select id="paired-difficulty">${['easy','medium','hard'].map(d=>`<option value="${d}" ${d===difficulty?'selected':''}>${d[0].toUpperCase()+d.slice(1)}</option>`).join('')}</select></label><p class="fine-print">All three AI use this difficulty. Everyone uses your saved handling speeds.</p><button id="paired-pool">Choose pattern pool</button><p class="fine-print" id="paired-pool-summary"></p><p id="paired-handling" class="fine-print">${fallSummary(prefs.rules)}</p><div class="button-row"><button class="primary" id="paired-start">Find a match</button><button id="paired-settings">Controls & feel</button></div></section>`;
  $('#paired-exit').onclick=onExit;$('#paired-pool').onclick=showPool;$('#paired-settings').onclick=showSettings;$('#paired-difficulty').onchange=e=>{difficulty=e.target.value;save('paired-difficulty',difficulty);};$('#paired-start').onclick=()=>start();
 }
 const board=(e,mini=false)=>`<section class="challenge-board ${mini?'mini':''}" id="paired-player-${e.id}"><div class="board-header"><div><strong>${e.name}${e.id?' · AI':''}</strong><span id="paired-state-${e.id}">Ready</span></div><div class="next-piece"><span>NEXT</span><canvas id="paired-next-${e.id}"></canvas></div></div><div class="board-frame"><canvas id="paired-board-${e.id}" role="img" aria-label="${e.name} puzzle board"></canvas></div><div class="challenge-board-foot"><span id="paired-incoming-${e.id}">No incoming</span><span id="paired-combo-${e.id}">—</span></div></section>`;
 function start(sameSeed=false){cleanup();session++;seed=sameSeed?seed:crypto.getRandomValues(new Uint32Array(1))[0];const blades=assignPatterns(seed,4,getPool());run=createPairedDuels({seed,difficulty,rules:{...prefs.rules,speedUp:true},patterns:blades.map(p=>p.rows)});run.entries.forEach((e,i)=>e.swordName=blades[i].name);countdown=1200;paused=false;acc=0;saved=false;brains=run.entries.map(()=>({key:null,plan:null,at:0}));
  host.innerHTML=`<section class="room-heading game-heading"><div><p class="eyebrow">PAIRED DUELS · ${difficulty.toUpperCase()} AI</p><h1 id="paired-title">Find your opening.</h1></div><div class="match-tools"><button id="paired-feel">Controls & feel</button><button id="paired-pause" aria-label="Pause paired duels">Ⅱ</button><button id="paired-leave">Leave</button></div></section><div class="challenge-arena"><section class="table-surface challenge-main"><div class="challenge-hud"><div><span>YOUR OPPONENT</span><strong id="paired-target">—</strong></div><div><span>ROUND</span><strong id="paired-round">1 / 2</strong></div></div><div class="challenge-playfield">${board(run.entries[0])}<div class="game-overlay" id="paired-overlay"></div></div><p id="paired-feedback" class="challenge-feedback" role="status"></p><div class="touch-controls challenge-touch">${[['left','←'],['ccw','↶'],['cw','↷'],['right','→'],['drop','Drop']].map(([a,t])=>`<button data-paired-action="${a}" aria-label="${a}">${t}</button>`).join('')}</div></section><aside class="challenge-sidebar"><section class="panel"><p class="eyebrow">MATCHUPS</p><div id="paired-matchups"></div><div class="divider"></div><div id="paired-standings"></div><p class="fine-print">Only paired opponents exchange attacks. No random hazards.</p></section><div class="challenge-opponents">${run.entries.slice(1).map(e=>board(e,true)).join('')}</div></aside></div><div id="paired-results"></div>`;
  $('#paired-pause').onclick=()=>pause();$('#paired-feel').onclick=showSettings;$('#paired-leave').onclick=()=>{if(run.finished)return setup();pause(true);const A=globalThis.scrapsAsk;if(A)A({title:'Leave these duels?',body:'This match will not count.',yes:'Leave'}).then(ok=>{if(ok)setup();});else if(confirm('Leave these duels?'))setup();};
  for(const b of host.querySelectorAll('[data-paired-action]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press('touch-'+b.dataset.pairedAction,b.dataset.pairedAction);};b.onpointerup=b.onpointercancel=()=>release('touch-'+b.dataset.pairedAction);}
  for(let i=1;i<4;i++){try{const worker=new Worker('/ai-worker.js',{type:'module'});workers[i]=worker;worker.onmessage=({data})=>{const b=brains[i];if(data.id===b.key){if(data.error){worker.terminate();workers[i]=null;b.key=null;}else b.plan=[...(data.plan?.path??[]),'fastOn'];}};worker.onerror=()=>{worker.terminate();workers[i]=null;brains[i].key=null;};}catch{brains[i].plan=['fastOn'];}}
  sound('start');
 }
 function press(code,action){if(!run||run.finished)return;if(action==='pause'){pause();return;}if(paused||countdown>0||run.entries[0].status!=='playing')return;held.set(code,{action,next:run.elapsed+run.rules.repeatDelayMs});actions.push({side:0,action:action==='drop'?'fastOn':action});if(['left','right','cw','ccw'].includes(action))sound(action==='cw'||action==='ccw'?'rotate':'move');}
 function release(code){const h=held.get(code);held.delete(code);if(h?.action==='drop')actions.push({side:0,action:'fastOff'});}
 function pause(force){if(!run||run.finished)return;paused=force??!paused;held.clear();actions=[];const p=pairedPlayer(run.entries[0]);if(p.fast){p.fall=p.fall/run.rules.fastFallMs*run.rules.gravityMs;p.fast=false;}
  set('#paired-pause',paused?'▶':'Ⅱ');const overlay=$('#paired-overlay');overlay.classList.toggle('shown',paused);overlay.innerHTML=paused?'<div class="pause-card"><h2>Duels paused.</h2><button id="paired-resume" class="primary">Resume</button></div>':'';$('#paired-resume')?.addEventListener('click',()=>pause(false));
 }
 function tick(){if(!run||paused||run.finished)return;if(countdown>0){countdown-=DT;const overlay=$('#paired-overlay');overlay.classList.toggle('shown',countdown>0);overlay.innerHTML=countdown>0?'<div class="count-in">'+Math.ceil(countdown/400)+'</div>':'';return;}
  for(const h of held.values()){if(['left','right'].includes(h.action)&&run.elapsed>=h.next){actions.push({side:0,action:h.action});h.next=run.elapsed+run.rules.repeatMs;}if(run.entries[0].game.version<10&&h.action==='drop'&&pairedPlayer(run.entries[0]).phase==='fall'&&!pairedPlayer(run.entries[0]).fast)actions.push({side:0,action:'fastOn'});}
  for(let i=1;i<4;i++){const profile=botProfile(difficulty,i-1),e=run.entries[i],p=pairedPlayer(e),b=brains[i];if(e.status!=='playing'||p.phase!=='fall'||!p.active)continue;const key=session+':'+run.round+':'+p.nextIndex;
   if(key!==b.key){b.key=key;b.plan=workers[i]?null:[...planMove({board:p.board,active:p.active,nextPair:pairAt(seed,p.nextIndex,run.rules.breakerRate),opponent:{...profile,depth:1}}).path,'fastOn'];b.at=run.elapsed+profile.think;workers[i]?.postMessage({id:key,board:p.board,active:p.active,nextPair:pairAt(seed,p.nextIndex,run.rules.breakerRate),opponent:profile});}
   if(b.plan?.length&&run.elapsed>=b.at){actions.push({side:i,action:b.plan.shift()});b.at=run.elapsed+profile.actionMs;}
  }
  stepPairedDuels(run,DT,actions);actions=[];
  for(const e of run.events){if(e.type==='rematch'){held.clear();countdown=1200;sound('start');}if(e.side===0){if(e.type==='breaking')sound('clear',e.chain);if(e.type==='lock')sound('lock');if(e.type==='hit')sound('hit');}}
  if(run.finished)finish();
 }
 function finish(){if(saved)return;saved=true;cleanup();const stored=read('paired-records',{}),record=stored[difficulty]??{wins:0,played:0};record.played++;if(run.winner===0)record.wins++;stored[difficulty]=record;save('paired-records',stored);sound(run.winner===0?'win':'end');
  $('#paired-results').innerHTML=`<section class="panel challenge-result-card"><div><p class="eyebrow">DUELS COMPLETE</p><h2>${run.winner===null?'No survivor.':esc(run.entries[run.winner].name)+' wins.'}</h2><p class="muted">${difficulty} · ${record.wins} wins in ${record.played} matches on this browser</p></div><div class="button-row"><button class="primary" id="paired-again">New match</button><button id="paired-retry">Same seed</button><button id="paired-back">Match setup</button></div></section>`;
  $('#paired-again').onclick=()=>start();$('#paired-retry').onclick=()=>start(true);$('#paired-back').onclick=setup;$('#paired-pause').disabled=true;
 }
 function render(time){if(!run){set('#paired-handling',fallSummary(prefs.rules));set('#paired-pool-summary',getPool().map(p=>p.name).join(', '));return;}for(const e of run.entries){const p=pairedPlayer(e);drawBoard($('#paired-board-'+e.id),p,{time,gravityMs:run.rules.gravityMs,fastFallMs:run.rules.fastFallMs,ghost:prefs.ghost,reduced:prefs.reduced,renderAheadMs:!paused&&!run.finished&&e.status==='playing'&&countdown<=0?acc:0});drawNext($('#paired-next-'+e.id),pairAt(seed,previewIndex(p),run.rules.breakerRate));set('#paired-state-'+e.id,e.status==='playing'?'vs '+run.entries[e.opponentId].name:e.status==='waiting'?'Waiting for final':e.status==='winner'?'Winner':'Out');set('#paired-incoming-'+e.id,p.incoming.length?p.incoming.length+' queued':'No incoming');set('#paired-combo-'+e.id,p.stats.bestChain?'×'+p.stats.bestChain:'—');$('#paired-player-'+e.id).classList.toggle('eliminated',p.dead);$('#paired-player-'+e.id).classList.toggle('matched-opponent',run.entries[0].opponentId===e.id);}
  const human=run.entries[0];set('#paired-target',human.opponentId===null?'—':run.entries[human.opponentId].name);set('#paired-round',run.round+' / 2');set('#paired-feedback',human.status==='waiting'?'Duel won. Your board is paused while the other pair finishes.':human.status==='out'?'You’re out. Watching the remaining duel.':run.finished?'Match complete.':'Attacks from '+run.entries[human.opponentId]?.name+' only · '+run.entries[human.opponentId]?.swordName);
  $('#paired-matchups').closest('.challenge-sidebar').classList.add('paired-sidebar');
  $('#paired-matchups').closest('.challenge-sidebar').classList.add('paired-sidebar');
  const matchups=run.matches.map(m=>`<p class="paired-matchup">${m.ids.map(id=>run.entries[id].name).join(' vs ')} <span class="muted">${m.done?'· finished':''}</span></p>`).join('');if($('#paired-matchups').innerHTML!==matchups)$('#paired-matchups').innerHTML=matchups;
  const standings=pairedStandings(run).map(e=>`<div class="paired-standing"><strong>${e.name}</strong><span>${e.status==='playing'?'Playing':e.status==='waiting'?'Waiting':e.status==='winner'?'Winner':'Out'}</span><b>${e.wins} wins</b></div>`).join('');if($('#paired-standings').innerHTML!==standings)$('#paired-standings').innerHTML=standings;
 }
 function frame(t){if(disposed)return;const delta=Math.min(100,t-(last||t));last=t;if(run&&!paused&&!run.finished){acc+=delta;while(acc>=DT){tick();acc-=DT;}}else acc=0;render(t);raf=requestAnimationFrame(frame);}
 window.addEventListener('keydown',e=>{if(!run||document.querySelector('dialog[open]')||document.activeElement?.matches('input,select,textarea'))return;const action=actionFor(prefs.keys,e.code);if(action){e.preventDefault();if(!e.repeat)press(e.code,action);}},{signal:scope.signal});
 window.addEventListener('keyup',e=>release(e.code),{signal:scope.signal});window.addEventListener('blur',()=>pause(true),{signal:scope.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);},{signal:scope.signal});
 setup();raf=requestAnimationFrame(frame);
 return {isActive:()=>!!run&&!run.finished,pause:()=>pause(true),destroy(){disposed=true;scope.abort();cleanup();cancelAnimationFrame(raf);},getState:()=>run?{seed,difficulty,round:run.round,rules:run.rules,paused,finished:run.finished,winner:run.winner,players:run.entries.map(e=>({id:e.id,opponent:e.opponentId,status:e.status,pattern:e.swordName,stats:pairedPlayer(e).stats,turn:pairedPlayer(e).turn,board:pairedPlayer(e).board,queued:pairedPlayer(e).incoming.length}))}:null};
}
